import java.util.Scanner;

public class Main {
    public static int calculate(int n, int mod) {
        if (n <= 3) {
            return 0;
        }
        int last_result = 17;
        int result = 17;
        int max_size = (n - 1) * (n - 2) / 2 + 1;
        int flip = 1;
        int[][] dp_table = new int[2][max_size + 1];
        // Initialize dp_table[0][0..3]
        dp_table[0][0] = 1;
        dp_table[0][1] = 2;
        dp_table[0][2] = 2;
        dp_table[0][3] = 1;

        for (int m = 4; m < n; m++) {
            int total_pairs = m * (m - 1) / 2;
            result = (m + 1) * last_result;
            int partial_sum = 0;
            // Compute partial sums for i in [0, m-1]
            for (int i = 0; i < m; i++) {
                partial_sum += dp_table[flip ^ 1][i];
                dp_table[flip][i] = partial_sum % mod;
            }
            // Compute for i in [m, total_pairs/2]
            for (int i = m; i <= total_pairs / 2; i++) {
                partial_sum += dp_table[flip ^ 1][i];
                partial_sum -= dp_table[flip ^ 1][i - m];
                dp_table[flip][i] = partial_sum % mod;
            }
            // Mirror the values for i in [total_pairs/2 + 1, total_pairs]
            for (int i = 0; i <= total_pairs / 2; i++) {
                dp_table[flip][total_pairs - i] = dp_table[flip][i];
            }
            int total_acc = 0;
            for (int i = 0; i < total_pairs; i++) {
                int temp_sum = 0;
                int start_j = Math.max(1, -total_pairs + i + m + 2);
                for (int j = start_j; j <= m; j++) {
                    int index = m + 2 - j + i;
                    if (index >= 0 && index <= total_pairs) {
                        temp_sum += j * dp_table[flip][index];
                    }
                }
                total_acc += dp_table[flip][i];
                total_acc %= mod;
                temp_sum %= mod;
                result += temp_sum * total_acc;
                result %= mod;
            }
            last_result = result;
            flip ^= 1;
        }
        return result % mod;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int mod = scanner.nextInt();
        System.out.println(calculate(n, mod));
        scanner.close();
    }
}
